+import assert from 'node:assert/strict';
+import { describe, it } from 'node:test';
+import { calculateEta } from '../src/services/eta.ts';
+import { Store } from '../src/store.ts';
+
+function seed(n: number): Store {
+  const store = new Store();
+  const base = Date.parse('2026-01-01T00:00:00Z');
+  for (let i = 0; i < n; i++) {
+    // shuffled creation times, with deliberate ties
+    const at = new Date(base + ((i * 7919) % 2500) * 60_000);
+    store.addShipment(
+      {
+        trackingNumber: `T${i}`,
+        carrier: i % 2 ? 'DHL' : 'GLS',
+        serviceLevel: 'standard',
+        recipient: { name: 'x', address: 'y', phone: 'z' },
+      } as any,
+      at,
+    );
+  }
+  return store;
+}
+
+describe('listShipments on a large dataset', () => {
+  const store = seed(5000);
+
+  it('matches a full stable sort for filters and limits', () => {
+    for (const filter of [{ limit: 50 }, { limit: 500 }, { limit: 50, carrier: 'DHL' }, { limit: 7, status: 'created' }]) {
+      const expected = store
+        .listShipments({ ...filter, limit: undefined })
+        .slice(0, filter.limit);
+      assert.deepEqual(store.listShipments(filter).map((s) => s.id), expected.map((s) => s.id));
+    }
+  });
+
+  it('lists 50 of 5000 shipments with ETAs quickly, ETAs always fresh', () => {
+    const t0 = performance.now();
+    for (let i = 0; i < 20; i++) {
+      store.listShipments({ limit: 50 }).map((s) => calculateEta(s, store.eventsFor(s.id)));
+    }
+    const perCall = (performance.now() - t0) / 20;
+    assert.ok(perCall < 20, `list took ${perCall.toFixed(2)} ms per call`);
+
+    const [first] = store.listShipments({ limit: 1 });
+    const before = calculateEta(first, store.eventsFor(first.id));
+    store.addEvent(first.id, 'exception');
+    assert.notEqual(calculateEta(first, store.eventsFor(first.id)), before);
+  });
+});
